  async function ensureExportHistoryLoaded(run, onProgress) {
    let current = findEpisodeHistory();
    if (!current) throw new Error("에피소드 기록을 찾지 못했어요");
    if (domHistoryReachedStart(current)) return;

    if (!run.historyScroll) {
      run.historyScroll = {
        wasAtTop: current.scroller.scrollTop <= 4,
        bottomGap: current.scroller.scrollHeight - current.scroller.scrollTop
      };
    }


    let stableRounds = 0;
    let batches = 0;
    while (!run.cancelled && location.href === run.url && stableRounds < 6 && batches < 160) {
      current = findEpisodeHistory();
      if (!current?.scroller.isConnected || domHistoryReachedStart(current)) break;
      const beforeIds = historyGroupIds(current.list);
      optimizeHistoryList(current.list, current.scroller);
      onProgress?.(`원본 기록 불러오는 중 · 메시지 ${beforeIds.size}개`);
      current.scroller.scrollTop = 0;
      current.scroller.dispatchEvent(new Event("scroll", { bubbles: true }));
      const changed = await waitForHistoryChange(run, beforeIds);
      const refreshed = findEpisodeHistory();
      if (!refreshed) break;
      if (changed) {
        stableRounds = 0;
        batches += 1;
        optimizeHistoryList(refreshed.list, refreshed.scroller);

      } else {
        stableRounds += 1;
      }
      // Keep the loader at the history boundary. Restoring the previous anchor
      // after every batch made the page visibly bounce and could prevent the
      // next top-edge request from firing.
      refreshed.scroller.scrollTop = 0;
      await waitForIdle();
    }

    current = findEpisodeHistory();
    if (!current || !domHistoryReachedStart(current)) {
      throw new Error("전체 원본 기록을 불러오지 못했어요. 잠시 후 다시 시도해 주세요");
    }
    optimizeHistoryList(current.list, current.scroller);


  }

  function restoreExportHistoryScroll(run) {
    if (run?.url !== location.href) return;
    const state = run?.historyScroll;
    const current = findEpisodeHistory();
    if (!state || !current?.scroller.isConnected) return;
    current.scroller.scrollTop = state.wasAtTop
      ? 0
      : Math.max(0, current.scroller.scrollHeight - state.bottomGap);
  }

  function exportMessageDescriptors() {
    let latestUser = null;
    const descriptors = [];
    for (const item of currentHistoryItems()) {
      if (item.role === "user") {
        latestUser = item;
        continue;
      }
      if (!item.counted) continue;
      if (!item.block?.isConnected) {
        throw new Error(`출력 ${item.turn}의 원본 컨테이너를 찾지 못했어요`);
      }
      descriptors.push({
        turn: item.turn,
        outputBlock: item.block,
        userBlock: latestUser?.block?.isConnected ? latestUser.block : null
      });
    }
    return descriptors;
  }

  function removeExportControls(root) {
    root.querySelectorAll([
      ".uc-message-meta",
      ".uc-section-toggle",
      '[role="menu"]',
      'button[aria-label="메시지 옵션"]',
      '[data-uc-message-action]'
    ].join(",")).forEach((element) => {
      let target = element;
      for (let depth = 0; depth < 3; depth += 1) {
        const parent = target.parentElement;
        if (!parent || parent === root) break;
        const remainingText = (parent.textContent || "").replace((target.textContent || ""), "").trim();
        const remainingMedia = Array.from(parent.querySelectorAll("img, video, canvas")).some((media) => !target.contains(media));
        if (remainingText || remainingMedia || parent.children.length > 1) break;
        target = parent;
      }
      target.remove();
    });

    root.querySelectorAll("button, [role='button'], input, textarea, select").forEach((element) => element.remove());
    root.querySelectorAll("*").forEach((element) => {
      for (const attribute of Array.from(element.attributes)) {
        if (attribute.name.startsWith("data-uc-")) element.removeAttribute(attribute.name);
      }
      element.classList.remove("uc-nav-flash");
      element.style.removeProperty("--uc-pin-color");
    });
    for (const attribute of Array.from(root.attributes)) {
      if (attribute.name.startsWith("data-uc-")) root.removeAttribute(attribute.name);
    }
    root.classList.remove("uc-nav-flash");
    root.style.removeProperty("--uc-pin-color");
    root.style.width = "100%";
    root.style.margin = "0";
  }

  function cloneMessageForExport(block) {
    const clone = block.cloneNode(true);
    removeExportControls(clone);
    clone.querySelectorAll("img").forEach((image) => {
      image.removeAttribute("srcset");
      image.removeAttribute("sizes");
      image.loading = "eager";
      image.decoding = "sync";
    });
    clone.querySelectorAll("video").forEach((video) => {
      const poster = video.poster || video.getAttribute("poster");
      if (!poster) {
        video.remove();
        return;
      }
      const image = document.createElement("img");
      image.src = poster;
      image.alt = video.getAttribute("aria-label") || "동영상 미리보기";
      image.style.cssText = video.style.cssText;
      video.replaceWith(image);
    });
    return clone;
  }

  function mosaicTokens(value) {
    return Array.from(new Set(String(value || "")
      .split(",")
      .map((token) => token.trim())
      .filter(Boolean)))
      .sort((a, b) => b.length - a.length);
  }

  function isMosaicWordCharacter(value) {
    return Boolean(value) && /[\p{L}\p{N}_]/u.test(value);
  }

  function hasKoreanParticleSuffix(text, index) {
    const tail = text.slice(index);
    const hangulRun = tail.match(/^[가-힣]+/u)?.[0] || "";
    if (!hangulRun || isMosaicWordCharacter(tail[hangulRun.length] || "")) return false;

    // Korean particles can stack (for example 에게 + 로, 으로부터 + 는).
    // Accept the suffix only when the entire following Hangul run can be
    // segmented into known particles, so lexical continuations stay visible.
    const reachable = new Array(hangulRun.length + 1).fill(false);
    reachable[0] = true;
    for (let offset = 0; offset < hangulRun.length; offset += 1) {
      if (!reachable[offset]) continue;
      for (const particle of KOREAN_PARTICLE_SUFFIXES) {
        if (hangulRun.startsWith(particle, offset)) {
          reachable[offset + particle.length] = true;
        }
      }
    }
    return reachable[hangulRun.length];
  }

  function isExactMosaicMatch(text, index, token) {
    const before = index > 0 ? text[index - 1] : "";
    const after = text[index + token.length] || "";
    if (isMosaicWordCharacter(token[0]) && isMosaicWordCharacter(before)) return false;
    if (isMosaicWordCharacter(token[token.length - 1]) && isMosaicWordCharacter(after)) {
      const endsWithKorean = /[가-힣]$/.test(token);
      if (!endsWithKorean || !hasKoreanParticleSuffix(text, index + token.length)) return false;
    }
    return true;
  }

  function applyMosaicWords(root, tokens) {
    if (!tokens.length) return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        const parent = node.parentElement;
        if (!node.data || !parent || parent.closest(".ucc-export-mosaic, script, style")) {
          return NodeFilter.FILTER_REJECT;
        }
        return NodeFilter.FILTER_ACCEPT;
      }
    });
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);

    nodes.forEach((node) => {
      const text = node.data;
      const matches = [];
      let cursor = 0;
      while (cursor < text.length) {
        const token = tokens.find((candidate) =>
          text.startsWith(candidate, cursor) && isExactMosaicMatch(text, cursor, candidate)
        );
        if (token) {
          matches.push({ index: cursor, token });
          cursor += token.length;
        } else {
          cursor += 1;
        }
      }
      if (!matches.length) return;

      const fragment = document.createDocumentFragment();
      let offset = 0;
      matches.forEach(({ index, token }) => {
        if (index > offset) fragment.append(document.createTextNode(text.slice(offset, index)));
        const mosaic = document.createElement("span");
        mosaic.className = "ucc-export-mosaic";
        mosaic.textContent = token;
        fragment.append(mosaic);
        offset = index + token.length;
      });
      if (offset < text.length) fragment.append(document.createTextNode(text.slice(offset)));
      node.replaceWith(fragment);
    });
  }

  function createExportStage(descriptors, includeUser, tokens) {
    const history = findEpisodeHistory();
    const sourceWidth = Math.ceil(history?.list.getBoundingClientRect().width || 768);
    const width = Math.max(320, sourceWidth);
    const stage = document.createElement("div");
    stage.className = "ucc-export-stage";
    stage.style.width = `${width}px`;
    const sheet = document.createElement("div");
    sheet.className = "ucc-export-sheet";

    descriptors.forEach((descriptor) => {
      const entry = document.createElement("section");
      entry.className = "ucc-export-entry";
      if (includeUser && descriptor.userBlock) {
        const user = document.createElement("div");
        user.className = "ucc-export-user";
        user.append(cloneMessageForExport(descriptor.userBlock));
        applyMosaicWords(user, tokens);
        entry.append(user);
      }
      const output = document.createElement("div");
      output.className = "ucc-export-output";
      output.append(cloneMessageForExport(descriptor.outputBlock));
      applyMosaicWords(output, tokens);
      entry.append(output);
      sheet.append(entry);
    });

    stage.append(sheet);
    document.body.append(stage);
    return { stage, sheet };
  }

  function blobToDataUrl(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.addEventListener("load", () => resolve(String(reader.result || "")), { once: true });
      reader.addEventListener("error", () => reject(reader.error || new Error("이미지 읽기 실패")), { once: true });
      reader.readAsDataURL(blob);
    });
  }

  function exportImageDataUrl(url) {
    const source = String(url || "");
    if (!source || source.startsWith("data:")) return Promise.resolve(source);
    if (exportImageCache.has(source)) return exportImageCache.get(source);
    const request = (async () => {
      try {
        const response = await fetch(source, { credentials: "omit", cache: "force-cache" });
        if (!response.ok) throw new Error(`image request failed: ${response.status}`);
        return await blobToDataUrl(await response.blob());
      } catch {
        return fetchImageThroughExtension(source);
      }
    })();
    exportImageCache.set(source, request);
    return request;
  }

  function waitForExportImage(image) {
    if (image.complete && image.naturalWidth) return Promise.resolve();
    return new Promise((resolve) => {
      const done = () => resolve();
      image.addEventListener("load", done, { once: true });
      image.addEventListener("error", done, { once: true });
      setTimeout(done, 8000);
    });
  }

  async function prepareExportMedia(sheet) {
    const images = Array.from(sheet.querySelectorAll("img"));
    for (let index = 0; index < images.length; index += 4) {
      await Promise.all(images.slice(index, index + 4).map(async (image) => {
        const source = image.currentSrc || image.src;
        if (!source) return;
        try {
          image.src = await exportImageDataUrl(source);
        } catch {
          throw new Error("출력 이미지를 불러오지 못했어요. 이미지 주소 접근 권한을 확인해 주세요");
        }
        await waitForExportImage(image);
      }));
    }
    if (document.fonts?.ready) await Promise.race([document.fonts.ready, wait(3000)]);
  }

  function inlineExportStyles(sourceRoot, cloneRoot) {
    const sources = [sourceRoot, ...sourceRoot.querySelectorAll("*")];
    const clones = [cloneRoot, ...cloneRoot.querySelectorAll("*")];
    sources.forEach((source, index) => {
      const target = clones[index];
      if (!target) return;
      const computed = getComputedStyle(source);
      EXPORT_STYLE_PROPERTIES.forEach((property) => {
        const value = computed.getPropertyValue(property);
        if ((property === "background" || property === "background-image") && /url\(/i.test(value)) return;
        if (value) target.style.setProperty(property, value);
      });
    });
  }

  function loadSvgImage(url) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.addEventListener("load", () => resolve(image), { once: true });
      image.addEventListener("error", () => reject(new Error("이미지 렌더링에 실패했어요")), { once: true });
      image.src = url;
    });
  }

  function canvasPngBlob(canvas) {
    return new Promise((resolve, reject) => {
      canvas.toBlob((blob) => {
        if (blob) resolve(blob);
        else reject(new Error("PNG 파일을 만들지 못했어요"));
      }, "image/png");
    });
  }

  async function measureExportSheet(sheet, widthScale) {
    await prepareExportMedia(sheet);
    const width = Math.max(1, Math.ceil(sheet.getBoundingClientRect().width));
    const height = Math.max(1, Math.ceil(sheet.scrollHeight));
    return {
      width,
      height,
      outputWidth: Math.max(1, Math.round(width * widthScale)),
      outputHeight: Math.max(1, Math.round(height * widthScale))
    };
  }

  function exportSegmentRanges(sheet, metrics, widthScale, maxOutputHeight) {
    if (metrics.outputHeight <= maxOutputHeight) return [{ top: 0, height: metrics.height }];
    const maxCssHeight = maxOutputHeight / widthScale;
    const sheetTop = sheet.getBoundingClientRect().top;
    const entryBottoms = Array.from(sheet.children)
      .map((entry) => entry.getBoundingClientRect().bottom - sheetTop)
      .filter((bottom) => bottom > 0 && bottom < metrics.height)
      .sort((a, b) => a - b);
    const ranges = [];
    let top = 0;
    while (top < metrics.height - 1) {
      const limit = Math.min(metrics.height, top + maxCssHeight);
      let bottom = limit;
      if (limit < metrics.height) {
        const boundary = entryBottoms.filter((candidate) => candidate > top + 120 && candidate <= limit).at(-1);
        if (boundary) bottom = boundary;
      }
      if (bottom <= top + 1) bottom = limit;
      ranges.push({ top, height: bottom - top });
      top = bottom;
    }
    return ranges;
  }

  async function renderExportSheet(sheet, metrics, widthScale, splitLongImage) {
    const recommendedHeight = 10000;
    const hardCanvasHeight = 30000;
    const segmentHeight = splitLongImage ? recommendedHeight : hardCanvasHeight;
    const ranges = exportSegmentRanges(sheet, metrics, widthScale, segmentHeight);

    const clone = sheet.cloneNode(true);
    inlineExportStyles(sheet, clone);
    clone.setAttribute("xmlns", "http://www.w3.org/1999/xhtml");
    clone.style.margin = "0";
    const serialized = new XMLSerializer().serializeToString(clone);
    const blobs = [];
    for (const range of ranges) {
      const cssHeight = Math.max(1, Math.ceil(range.height));
      const cssTop = Math.max(0, range.top);
      const viewport = `<div xmlns="http://www.w3.org/1999/xhtml" style="position:relative;width:${metrics.width}px;height:${cssHeight}px;overflow:hidden;background:#111113"><div style="position:absolute;top:-${cssTop}px;left:0;width:${metrics.width}px">${serialized}</div></div>`;
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${metrics.width}" height="${cssHeight}" viewBox="0 0 ${metrics.width} ${cssHeight}"><foreignObject width="100%" height="100%">${viewport}</foreignObject></svg>`;
      const svgUrl = await blobToDataUrl(new Blob([svg], { type: "image/svg+xml;charset=utf-8" }));
      const image = await loadSvgImage(svgUrl);
      const canvas = document.createElement("canvas");
      canvas.width = metrics.outputWidth;
      canvas.height = Math.max(1, Math.round(cssHeight * widthScale));
      const context = canvas.getContext("2d", { alpha: false });
      if (!context) throw new Error("이미지 캔버스를 만들지 못했어요");
      context.fillStyle = "#111113";
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(image, 0, 0, canvas.width, canvas.height);
      blobs.push(await canvasPngBlob(canvas));
    }
    return blobs;
  }

  function outputFileName(start, end, digits, partIndex = 0, partCount = 1) {
    const first = String(start).padStart(digits, "0");
    const last = String(end).padStart(digits, "0");
    const base = start === end ? `출력_${first}` : `출력_${first}-${last}`;
    const part = partCount > 1 ? `_분할_${String(partIndex + 1).padStart(2, "0")}` : "";
    return `${base}${part}.png`;
  }

  function confirmLongImageSplit(height) {
    return new Promise((resolve) => {
      let settled = false;
      const finish = (value, overlay) => {
        if (settled) return;
        settled = true;
        overlay.remove();
        resolve(value);
      };
      const { overlay, dialog } = createAnnotationOverlay("긴 이미지 분할을 권장해요");
      const help = document.createElement("p");
      help.className = "ucc-annotation-help";
      help.textContent = `예상 세로 길이가 약 ${Math.round(height).toLocaleString("ko-KR")}px입니다. 가로폭과 글자 크기를 유지하려면 10,000px 안팎으로 나눠 저장하는 것을 권장해요. 브라우저 한계를 넘는 경우에는 선택과 관계없이 안전하게 분할됩니다.`;
      const actions = document.createElement("div");
      actions.className = "ucc-annotation-actions";
      const cancel = annotationButton("취소", "ucc-annotation-danger");
      const single = annotationButton("한 장으로 계속");
      const split = annotationButton("분할 저장", "ucc-annotation-primary");
      cancel.addEventListener("click", () => finish("cancel", overlay));
      single.addEventListener("click", () => finish("single", overlay));
      split.addEventListener("click", () => finish("split", overlay));
      dialog.append(help, actions);
      actions.append(cancel, single, split);
      requestAnimationFrame(() => split.focus());
      dialog.querySelector(".ucc-annotation-close")?.addEventListener("click", () => finish("cancel", overlay), { once: true });
      overlay.addEventListener("pointerdown", (event) => {
        if (event.target === overlay) finish("cancel", overlay);
      }, { once: true });
      overlay.addEventListener("keydown", (event) => {
        if (event.key === "Escape") finish("cancel", overlay);
      });
    });
  }

  function confirmIndividualImageExport(count) {
    return new Promise((resolve) => {
      let settled = false;
      const finish = (value, overlay) => {
        if (settled) return;
        settled = true;
        overlay.remove();
        resolve(value);
      };
      const { overlay, dialog, dismiss } = createAnnotationOverlay("ZIP 내보내기를 권장해요");
      const help = document.createElement("p");
      help.className = "ucc-annotation-help";
      help.textContent = `이미지 ${count}장을 각각 저장하면 브라우저에서 여러 파일 다운로드 허용을 요청할 수 있어요. ZIP을 켜는 것을 권장합니다.`;
      const actions = document.createElement("div");
      actions.className = "ucc-annotation-actions";
      const cancel = annotationButton("취소");
      const proceed = annotationButton("계속 진행", "ucc-annotation-primary");
      cancel.addEventListener("click", () => finish(false, overlay));
      proceed.addEventListener("click", () => finish(true, overlay));
      overlay.addEventListener("keydown", (event) => {
        if (event.key === "Escape") finish(false, overlay);
      });
      dialog.append(help, actions);
      actions.append(cancel, proceed);
      requestAnimationFrame(() => proceed.focus());

      const close = dialog.querySelector(".ucc-annotation-close");
      close?.addEventListener("click", () => finish(false, overlay), { once: true });
      overlay.addEventListener("pointerdown", (event) => {
        if (event.target === overlay) finish(false, overlay);
      }, { once: true });
      void dismiss;
    });
  }

  async function exportChatImages(root, mode) {
    const exporter = root.querySelector(".ucc-exporter");
    if (!exporter || exporter.dataset.available !== "true") {
      setImageExportStatus("에피소드 화면에서 사용할 수 있어요", "error");
      return;
    }

    const run = { url: location.href, cancelled: false };
    imageExportRun = run;
    setImageExportBusy(root, true);
    exportImageCache.clear();
    try {
      setImageExportStatus("전체 원본 기록을 확인하는 중…");
      await ensureExportHistoryLoaded(run, (message) => setImageExportStatus(message));
      if (run.cancelled || location.href !== run.url) throw new Error("페이지가 바뀌어 내보내기를 중지했어요");

      const all = exportMessageDescriptors();
      if (!all.length) throw new Error("내보낼 AI 출력이 없어요");
      const perInput = root.querySelector(`[data-export-per-image="${mode}"]`);
      const perImage = Number(perInput?.value);
      if (!Number.isInteger(perImage) || perImage < 1 || perImage > 20) {
        throw new Error("이미지당 출력 수는 1–20 사이로 입력해 주세요");
      }

      let selected = all;
      if (mode === "range") {
        const startValue = root.querySelector("[data-export-range-start]")?.value.trim();
        const endValue = root.querySelector("[data-export-range-end]")?.value.trim();
        const start = Number(startValue);
        const end = endValue ? Number(endValue) : all[all.length - 1].turn;
        const lastTurn = all[all.length - 1].turn;
        if (!startValue || !Number.isInteger(start) || !Number.isInteger(end) || start < 0 || end < start || end > lastTurn) {
          throw new Error(`출력 범위는 0–${lastTurn} 안에서 시작 ≤ 끝으로 입력해 주세요`);
        }
        selected = all.filter((item) => item.turn >= start && item.turn <= end);
      }
      if (!selected.length) throw new Error("선택한 범위에 내보낼 출력이 없어요");

      const includeUser = Boolean(root.querySelector("[data-export-include-user]")?.checked);
      const useZip = Boolean(root.querySelector("[data-export-zip]")?.checked);
      const widthMode = root.querySelector("[data-export-width]")?.value === "half" ? "half" : "original";
      const widthScale = widthMode === "half" ? .5 : 1;
      const tokens = mosaicTokens(root.querySelector("[data-export-mosaic]")?.value);
      const chunks = [];
      for (let index = 0; index < selected.length; index += perImage) {
        chunks.push(selected.slice(index, index + perImage));
      }

      const digits = Math.max(3, String(all[all.length - 1].turn).length);
      const files = [];
      let longImageChoice = null;
      let exportPixelWidth = 0;
      for (let index = 0; index < chunks.length; index += 1) {
        if (run.cancelled || location.href !== run.url) throw new Error("내보내기를 중지했어요");
        const chunk = chunks[index];
        setImageExportStatus(`이미지 변환 중 · ${index + 1}/${chunks.length}`);
        const { stage, sheet } = createExportStage(chunk, includeUser, tokens);
        document.documentElement.dataset.uccLastExportMosaicCount = String(
          sheet.querySelectorAll(".ucc-export-mosaic").length
        );
        try {
          const metrics = await measureExportSheet(sheet, widthScale);
          if (!exportPixelWidth) exportPixelWidth = metrics.outputWidth;
          if (metrics.outputHeight >= 10000 && !longImageChoice) {
            setImageExportStatus(`긴 이미지 확인 필요 · ${metrics.outputWidth}×${metrics.outputHeight}px`);
            longImageChoice = await confirmLongImageSplit(metrics.outputHeight);
            if (longImageChoice === "cancel") {
              setImageExportStatus("이미지 내보내기를 취소했어요");
              return;
            }
          }
          setImageExportStatus(`이미지 변환 중 · ${index + 1}/${chunks.length} · ${metrics.outputWidth}×${metrics.outputHeight}px`);
          const blobs = await renderExportSheet(sheet, metrics, widthScale, longImageChoice === "split");
          blobs.forEach((blob, partIndex) => {
            files.push({
              name: outputFileName(
                chunk[0].turn,
                chunk[chunk.length - 1].turn,
                digits,
                partIndex,
                blobs.length
              ),
              blob
            });
          });
        } finally {
          stage.remove();
        }
        await waitForIdle();
      }

      if (!useZip && files.length >= 10) {
        setImageExportStatus(`개별 이미지 ${files.length}장 저장 전 확인이 필요해요`);
        const proceed = await confirmIndividualImageExport(files.length);
        if (!proceed) {
          setImageExportStatus("이미지 내보내기를 취소했어요");
          return;
        }
      }

      if (run.cancelled || location.href !== run.url) throw new Error("내보내기를 중지했어요");
      const title = safeExportName(document.title);
      const firstTurn = selected[0].turn;
      const lastTurn = selected[selected.length - 1].turn;
      if (useZip) {
        setImageExportStatus(`ZIP 묶는 중 · 이미지 ${files.length}장`);
        const zip = await createStoredZip(files);
        downloadBlob(zip, `${title}_출력_${firstTurn}-${lastTurn}.zip`);
      } else {
        for (let index = 0; index < files.length; index += 1) {
          downloadBlob(files[index].blob, `${title}_${files[index].name}`);
          if (index + 1 < files.length) await wait(180);
        }
      }
      document.documentElement.dataset.uccLastExportImages = String(files.length);
      document.documentElement.dataset.uccLastExportZip = String(useZip);
      document.documentElement.dataset.uccLastExportWidth = widthMode;
      document.documentElement.dataset.uccLastExportPixelWidth = String(exportPixelWidth);
      setImageExportStatus(`완료 · 출력 ${selected.length}개를 이미지 ${files.length}장으로 저장했어요 · 가로 ${exportPixelWidth}px`, "complete");
    } catch (error) {
      setImageExportStatus(error?.message || "이미지 내보내기에 실패했어요", "error");
    } finally {
      exportImageCache.clear();
      restoreExportHistoryScroll(run);
      imageExportRun = null;
      setImageExportBusy(root, false);
    }
  }
